// Builds a compact payload from the Error Trigger data and decides whether this is a
// duplicate. The anti-spam state lives in workflow static data: key -> last alert time.
const BASE_URL = 'http://localhost:5678';
const CHAT_ID = '';            // TODO: id of the ops Telegram chat
const TTL_MS = 60 * 60 * 1000; // anti-spam window: 1 hour

const esc = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const src = $input.first().json || {};
const wf = src.workflow || {};
const ex = src.execution || {};
const err = ex.error || {};

const workflowId = wf.id || 'unknown';
const workflowName = wf.name || 'unknown';
const executionId = ex.id === undefined || ex.id === null ? '' : String(ex.id);
const failedNode = ex.lastNodeExecuted || (err.node && err.node.name) || 'unknown';
const message = String(err.message || 'no error message').slice(0, 500);

const url = executionId
  ? BASE_URL + '/workflow/' + workflowId + '/executions/' + executionId
  : BASE_URL + '/workflow/' + workflowId;

// anti-spam
const store = $getWorkflowStaticData('global');
if (!store.alerts) store.alerts = {};
const now = Date.now();
for (const k of Object.keys(store.alerts)) {
  if (now - store.alerts[k] > TTL_MS) delete store.alerts[k];
}
const key = workflowId + '|' + failedNode + '|' + message;
const last = store.alerts[key];
const isDuplicate = typeof last === 'number' && (now - last) < TTL_MS;
if (!isDuplicate) store.alerts[key] = now;

const text = [
  '<b>n8n: workflow failed</b>',
  '',
  'Workflow: <b>' + esc(workflowName) + '</b>',
  'Node: <code>' + esc(failedNode) + '</code>',
  'Execution: <code>' + esc(executionId || 'none') + '</code>',
  '',
  'Error:',
  '<code>' + esc(message) + '</code>',
  '',
  '<a href="' + url + '">Open in n8n</a>'
].join('\n');

return [{
  json: {
    chatId: CHAT_ID,
    workflowId, workflowName, failedNode, executionId,
    message, url, isDuplicate, text,
  },
}];

// Outcome of the handler. The Telegram node runs with onError: continueRegularOutput,
// so a delivery failure is reported here instead of crashing the workflow.
const j = $input.first().json || {};
const failed = Boolean(j.error);
return [{
  json: {
    alerted: !failed,
    reason: failed ? 'telegram_failed: ' + String(j.error).slice(0, 200) : 'sent',
  },
}];
